\item Suppose $a, b, c, d$ are integers and the expression $\frac{a + b\sqrt{2} + c\sqrt{3}}{b + c\sqrt{2} + d\sqrt{3}}$ is rational. Prove that $ad = bc$.
\end{enumerate}

